package ec.dmt.admin.school;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @org.springframework.transaction.annotation.Transactional @RequestMapping("/api/parallels") public class SchoolParallelController { private final SchoolParallelRepository repo; private final CourseRepository courses; public SchoolParallelController(SchoolParallelRepository repo,CourseRepository courses){this.repo=repo;this.courses=courses;} @GetMapping public List<View> list(){return repo.findAll().stream().map(View::of).toList();} @PostMapping public ResponseEntity<View> create(@Valid @RequestBody Input in){SchoolParallel p=repo.save(new SchoolParallel(course(in.courseId()),in.name().trim(),in.active()));return ResponseEntity.status(201).body(View.of(p));} @PutMapping("/{id}") public View update(@PathVariable Long id,@Valid @RequestBody Input in){SchoolParallel p=find(id);p.update(course(in.courseId()),in.name().trim(),in.active());return View.of(repo.save(p));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.delete(find(id));} private SchoolParallel find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Paralelo no encontrado"));} private Course course(Long id){return courses.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Curso no encontrado"));} public record Input(@NotNull Long courseId,@NotBlank String name,boolean active){} public record View(Long id,Long courseId,String courseName,String name,boolean active){static View of(SchoolParallel p){return new View(p.getId(),p.getCourse().getId(),p.getCourse().getName(),p.isActive()?p.getName():p.getName(),p.isActive());}} }
